from google.cloud import documentai

def extract_invoice(invoice_bytes: bytes) -> dict:
    client = documentai.DocumentProcessorServiceClient()
    name = "projects/your-project/locations/us/processors/your_invoice_processor"
    document = {"content": invoice_bytes, "mime_type": "application/pdf"}
    request = {"name": name, "document": document}
    response = client.process_document(request=request)
    document = response.document

    fields = {}
    for entity in document.entities:
        if entity.type_ == "VENDOR":
            fields["vendor"] = entity.mention_text
        elif entity.type_ == "DATE":
            fields["date"] = entity.mention_text
        elif entity.type_ == "AMOUNT_DUE":
            fields["total"] = entity.mention_text
        # line items are handled separately below

    line_items = []
    for block in document.pages[0].blocks:
        if block.type_ == "TABLE":
            for row in block.layout.table.rows:
                item = {}
                for cell in row.cells:
                    text = "".join(cell.layout.text_anchor.content.splitlines())
                    if "Description" in text:
                        item["description"] = text.replace("Description", "").strip()
                    elif "Unit Price" in text:
                        item["unit_price"] = text.replace("Unit Price", "").strip()
                    elif "Quantity" in text:
                        item["quantity"] = text.replace("Quantity", "").strip()
                if item:
                    line_items.append(item)
    if line_items:
        fields["line_items"] = line_items

    return fields
